# Expand topic labels into mixed Myanmar-friendly names for question variety.
my_topic_alias = {
'insurance basics':'အာမခံအခြေခံ','premium':'Premium ပရီမီယံ','coverage':'Coverage အာမခံကာကွယ်မှု','deductible':'Deductible','exclusions':'Exclusion မပါဝင်သည့်အချက်များ','waiting period':'Waiting Period','claims':'Claim','underwriting':'Underwriting','policy limits':'Policy Limit','sum insured':'Sum Insured','grace period':'Grace Period','policy lapse':'Policy Lapse','renewal':'Renewal','beneficiary':'Beneficiary','riders':'Insurance Rider','pre-existing conditions':'Pre-existing Condition','life insurance':'Life Insurance','health insurance':'Health Insurance','vehicle insurance':'Vehicle Insurance','property insurance':'Property Insurance','business insurance':'Business Insurance','travel insurance':'Travel Insurance','critical illness insurance':'Critical Illness Insurance','personal accident insurance':'Personal Accident Insurance','liability insurance':'Liability Insurance','reinsurance':'Reinsurance','insurance fraud':'Insurance Fraud','insurance documents':'Insurance Documents','comparing plans':'Insurance Plan နှိုင်းယှဉ်ခြင်း','claim denial':'Claim Denial','claim documents':'Claim Documents','claim status':'Claim Status','cashless health claims':'Cashless Claim','reimbursement claims':'Reimbursement Claim','free-look period':'Free-look Period','material disclosure':'Material Disclosure','co-payment':'Co-payment','depreciation':'Depreciation','salvage':'Salvage','subrogation':'Subrogation','principle of indemnity':'Indemnity Principle',
}

def answer_for(base, domain, context, qualifier, lang):
    if lang == 'en':
        tail = f" In the context of {context}, apply this by checking the exact policy or portal record, keeping supporting evidence, and following the next authorized step. {qualifier.capitalize()} means the explanation should stay practical and should not promise approval, claim payment, or a binding quote unless the authorized company process confirms it."
        if domain == 'website':
            tail = f" For {context}, use the route and workflow above, verify the user has the correct role, and check status or validation messages before retrying. {qualifier.capitalize()}; never request passwords, OTPs, or full card details in chat."
        elif domain == 'business':
            tail = f" For {context}, turn this into a measurable workflow with clear ownership, status definitions, auditability, and customer-safe communication. {qualifier.capitalize()}; use data to support decisions but keep human review for high-impact exceptions."
    else:
        tail = f" {context} ဆိုတဲ့အခြေအနေမှာ သက်ဆိုင်ရာ policy သို့မဟုတ် portal record ကိုအရင်စစ်ပြီး supporting evidence ကိုပြည့်စုံအောင်ထားကာ authorized process အတိုင်းဆက်လုပ်သင့်ပါတယ်။ {qualifier} ရှင်းပြရာမှာ approval၊ claim payment သို့မဟုတ် final quote ကို company reviewer မအတည်ပြုမချင်း အာမခံမပြောသင့်ပါဘူး။"
        if domain == 'website':
            tail = f" {context} ဆိုတဲ့အခြေအနေမှာ အပေါ်က route/workflow ကိုသုံးပြီး user role မှန်မမှန်၊ status နဲ့ validation message တွေကိုစစ်ပါ။ {qualifier} ရှင်းပြနိုင်ပေမယ့် password၊ OTP၊ full card number ကို chat ထဲမှာမတောင်းသင့်ပါဘူး။"
        elif domain == 'business':
            tail = f" {context} ဆိုတဲ့အခြေအနေမှာ ဒီအချက်ကို measurable workflow အဖြစ်ပြောင်းပြီး owner၊ status definition၊ audit trail နဲ့ customer communication ကိုရှင်းလင်းထားသင့်ပါတယ်။ {qualifier} လုပ်နိုင်ပေမယ့် high-impact exception တွေမှာ human review ထားသင့်ပါတယ်။"
    return base + tail

rows=[]
seen=set()
# Target distribution exact: 25k insurance, 15k website, 10k business
quotas={'insurance':25000,'website':15000,'business':10000}
by_domain={d:[t for t in all_topics if t[1]==d] for d in quotas}

for domain, quota in quotas.items():
    topics=by_domain[domain]
    idx=0
    attempts=0
    while idx < quota:
        attempts += 1
        topic_id, dom, topic, base = topics[idx % len(topics)]
        # deterministic variety using mixed radix
        j = idx // len(topics)
        lang = 'en' if (j % 5) < 3 else 'my'  # ~60/40 EN/MY
        pidx = (j*3 + idx) % 20
        cidx = (j*7 + idx//3) % 20
        qidx = (j*11 + idx//5) % 10
        if lang=='en':
            pat=en_patterns[pidx]; context=contexts_en[cidx]; qual=qualifiers_en[qidx]; label=topic
            q=pat.format(topic=label)
            # Add context/qualifier to ensure uniqueness and realistic phrasing.
            if j % 2 == 0: q += f" Please answer {qual} {context}."
            else: q += f" I need this {context}, {qual}."
        else:
            pat=my_patterns[pidx]; context=contexts_my[cidx]; qual=qualifiers_my[qidx]; label=my_topic_alias.get(topic, topic)
            q=pat.format(topic=label)
            if j % 2 == 0: q += f" {context} {qual} ရှင်းပြပေးပါ။"
            else: q += f" {context} ဆိုရင် {qual} ပြောပေးပါ။"
        # collision fallback
        if q in seen:
            q += f" Case {j+1}."
        seen.add(q)
        answer=answer_for(base, domain, context, qual, lang)
        keywords=' '.join(sorted(set(re.findall(r"[A-Za-z0-9_/.-]{3,}", (topic+' '+topic_id+' '+q).lower())))[:25])
        route=''
        m=re.search(r'`(/[^`]+)`', base)
        if m: route=m.group(1)
        rows.append({
            'id':f'QA{len(rows)+1:05d}', 'domain':domain, 'category':topic_id, 'intent':topic_id,
            'language':lang, 'question':q, 'answer':answer, 'keywords':keywords,
            'source_type':'curated_template', 'route':route
        })
        idx+=1

assert len(rows)==50000
assert len({r['question'] for r in rows})==50000

tsv=OUT/'insurance_website_qa_50000.tsv'
with tsv.open('w',encoding='utf-8',newline='') as f:
    w=csv.DictWriter(f,fieldnames=list(rows[0]),delimiter='\t',lineterminator='\n',quoting=csv.QUOTE_MINIMAL)
    w.writeheader(); w.writerows(rows)

